WITH flattened_attrs AS (SELECT id, service, host, latency_ms, status_code, payload_json, context, context['region'] AS region, ARRAY_CONTAINS(MAP_KEYS(context), 'trace') AS has_trace, CAST((status_code & 1) != 0 AS INT) AS flag_bit1 FROM app_logs WHERE status_code < 287) SELECT CASE WHEN flag_bit1 >= 1 THEN 'HIGH' ELSE 'LOW' END AS flag_bit1_tier, host, SUM(CASE WHEN host = 'h1' THEN latency_ms ELSE 0 END) AS h1_latency_ms, COUNT_IF(host = 'h1') AS h1_events, ROUND(AVG(latency_ms), 2) AS avg_latency_ms, COUNT(DISTINCT service) AS distinct_services, SIZE(COLLECT_SET(host)) AS num_hosts FROM flattened_attrs GROUP BY CASE WHEN flag_bit1 >= 1 THEN 'HIGH' ELSE 'LOW' END, host HAVING avg_latency_ms < 0;
